32	var (
33		rootCmd = &cobra.Command{
34			Use:   "memos",
35			Short: `An open source, lightweight note-taking service. Easily capture and share your great thoughts.`,
36			Run: func(_ *cobra.Command, _ []string) {
37				instanceProfile := &profile.Profile{
38					Demo:        viper.GetBool("demo"),
39					Addr:        viper.GetString("addr"),
40					Port:        viper.GetInt("port"),
41					UNIXSock:    viper.GetString("unix-sock"),
